#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_ALLOWED 1024   /* maximum length that is accepted (0x400) */

static void count_chars(const char *s, int cnt[256])
{
    for ( ; *s != '\0'; ++s ) {
        unsigned char c = (unsigned char)*s;

        if (c == ' ')               /* spaces are ignored */
            continue;

        if (c >= 'A' && c <= 'Z')   /* case‑insensitive for letters */
            c = (unsigned char)(c + 0x20);   /* to lower case */

        cnt[c]++;                   /* count the byte value */
    }
}

int main(int argc, char *argv[])
{
    /* usage check */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    /* length check – both arguments must be shorter than 1025 bytes
       (the original program accepts lengths up to 1024) */
    if (strlen(argv[1]) > MAX_ALLOWED || strlen(argv[2]) > MAX_ALLOWED) {
        puts("TOO_LONG");
        return 0;
    }

    int cnt1[256] = {0};
    int cnt2[256] = {0};

    count_chars(argv[1], cnt1);
    count_chars(argv[2], cnt2);

    /* compare the two frequency tables */
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) {
            puts("NOT_ANAGRAM");
            return 0;
        }
    }

    puts("ANAGRAM");
    return 0;
}
